CREATE OR REPLACE FUNCTION public.pm_parse_payment_terms(_terms text) RETURNS integer LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE v text; m text[]; word text; BEGIN v:=lower(trim(regexp_replace(translate(coalesce(_terms,''),'áàãâéêíóôõúç','aaaaeeiooouc'),'\s+',' ','g'))); IF v IN ('pronto pagamento','pagamento imediato','immediate payment','payable on receipt','due on receipt','cash on delivery') THEN RETURN 0; END IF; m:=regexp_match(v,'^([0-9]{1,3})( [(][a-z ]+[)])? dias( de calendario)?$'); IF m IS NOT NULL THEN IF m[2] IS NOT NULL THEN word:=trim(translate(m[2],'()','')); IF word IS DISTINCT FROM (CASE m[1] WHEN '0' THEN 'zero' WHEN '15' THEN 'quinze' WHEN '30' THEN 'trinta' WHEN '45' THEN 'quarenta e cinco' WHEN '60' THEN 'sessenta' WHEN '90' THEN 'noventa' END) THEN RETURN NULL; END IF; END IF; RETURN m[1]::integer; END IF; m:=regexp_match(v,'^(net )?([0-9]{1,3}) (calendar )?days$'); IF m IS NOT NULL THEN RETURN m[2]::integer; END IF; RETURN NULL; END $$;